 "content": "def transform(grid):
    """Move every 4 down one cell; on landing immediately above the 2-barrier,
    split it into upward diagonals."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    barrier_rows = [r for r, row in enumerate(grid) if row and all(v == 2 for v in row)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 4:
                continue
            out[r][c] = 0
            nr = r + 1
            # A 4 moves one row down where possible.
            if nr >= h or grid[nr][c] != 0:
                out[r][c] = 4
                continue
            if nr + 1 < h and grid[nr + 1][c] == 2:
                # It has reached the cell directly above the barrier: fan upward.
                out[nr][c] = 4
                for dc in (-1, 1):
                    rr, cc = nr - 1, c + dc
                    while 0 <= rr < h and 0 <= cc < w:
                        if grid[rr][cc] == 2:
                            break
                        out[rr][cc] = 4
                        rr -= 1
                        cc += dc
            else:
                out[nr][c] = 4
    return out
